import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 근태 담당자는 전체/부서/개인 조회, 임직원은 개인(본인)만 조회한다.
// 가정: 승인·마감 상태의 근태 신청만 근태 현황과 집계에 반영한다.
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const SCOPES = ['전체', '부서', '개인'];
const DATE_FORMAT = /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/;
const ID_FORMAT = /^[0-9]+$/;

type User = ReturnType<typeof currentUser>;

type Db = {
  query(sql: string, params?: Record<string, unknown>): Promise<any[]>;
};

interface Filter {
  params: Record<string, unknown>;
  page: number;
  size: number;
}

// 근태 일자별 행: 승인된 근태 신청을 일자로 펼친다
const WITH_SQL = `
  WITH att AS (
    SELECT ar.employee_id, CAST(g AS date) AS work_date, ar.attendance_type
    FROM attendance_request ar
    CROSS JOIN LATERAL generate_series(
      GREATEST(ar.start_date, CAST(:startDate AS date)),
      LEAST(ar.end_date, CAST(:endDate AS date)),
      interval '1 day'
    ) g
    WHERE ar.approval_status IN ('승인', '마감')
  ),
  cr AS (
    SELECT employee_id, work_date, check_in_at, check_out_at
    FROM commute_record
    WHERE work_date BETWEEN CAST(:startDate AS date) AND CAST(:endDate AS date)
  ),
  days AS (
    SELECT employee_id, work_date FROM att
    UNION
    SELECT employee_id, work_date FROM cr
  )
`;

const WHERE_SQL = `
  WHERE (CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint))
    AND (CAST(:employeeId AS bigint) IS NULL OR e.employee_id = CAST(:employeeId AS bigint))
`;

function isManager(user: User): boolean {
  try {
    user.require('근태 담당자');
    return true;
  } catch {
    return false;
  }
}

function text(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function optionalId(value: unknown, label: string): string | null {
  const v = text(value);
  if (v === '') {
    return null;
  }
  if (!ID_FORMAT.test(v)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 형식이 올바르지 않습니다.');
  }
  return v;
}

function readFilter(req: Request, user: User): Filter {
  const q = checks.queryOf(req.query) as Record<string, unknown>;
  const startDate = text(q['startDate']);
  const endDate = text(q['endDate']);
  const scope = text(q['scope']);
  if (!DATE_FORMAT.test(startDate) || !DATE_FORMAT.test(endDate)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '조회 기간을 YYYY-MM-DD 형식으로 입력해 주세요.');
  }
  if (startDate > endDate) {
    throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일은 종료일보다 늦을 수 없습니다.');
  }
  if (!SCOPES.includes(scope)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '조회 범위를 선택해 주세요.');
  }
  let departmentId = optionalId(q['departmentId'], '부서');
  let employeeId = optionalId(q['employeeId'], '임직원');
  if (!isManager(user)) {
    if (scope !== '개인' || (employeeId !== null && employeeId !== user.id)) {
      throw new ApiError(422, 'SCOPE_NOT_PERMITTED', '조회 권한 범위를 벗어난 요청입니다.');
    }
    employeeId = user.id;
    departmentId = null;
  } else if (scope === '개인') {
    if (employeeId === null) {
      employeeId = user.id;
    }
  } else if (scope === '부서' && departmentId === null) {
    throw new ApiError(400, 'VALIDATION_FAILED', '부서를 선택해 주세요.');
  }
  const pageText = text(q['page']);
  const sizeText = text(q['size']);
  const page = pageText === '' ? 0 : Number(pageText);
  const size = sizeText === '' ? DEFAULT_SIZE : Number(sizeText);
  if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
    throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호나 쪽 크기가 올바르지 않습니다.');
  }
  return {
    params: { startDate, endDate, departmentId, employeeId },
    page,
    size: Math.min(size, MAX_SIZE),
  };
}

async function listOf(db: Db, selectSql: string, orderBy: string, filter: Filter) {
  const totalRows = await db.query(
    WITH_SQL + 'SELECT COUNT(*) AS "total" FROM (' + selectSql + ') t',
    filter.params,
  );
  const items = await db.query(
    WITH_SQL + selectSql + ' ORDER BY ' + orderBy + ' LIMIT :limit OFFSET :offset',
    { ...filter.params, limit: filter.size, offset: filter.page * filter.size },
  );
  return {
    items,
    page: filter.page,
    size: filter.size,
    total: Number(totalRows[0].total),
  };
}

@Controller('api/v1')
export class FnSfr01805Controller {
  @Get('/attendance-status/daily')
  async listDailyAttendanceStatus(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자');
    const filter = readFilter(req, user);
    return transaction(async (db) => {
      const selectSql = `
        SELECT e.name AS "employeeName",
               d.name AS "departmentName",
               to_char(days.work_date, 'YYYY-MM-DD') AS "workDate",
               cr.check_in_at AS "checkInAt",
               cr.check_out_at AS "checkOutAt",
               att.attendance_type AS "attendanceType",
               e.employee_id AS "sortEmployeeId",
               days.work_date AS "sortWorkDate"
        FROM days
        JOIN employee e ON e.employee_id = days.employee_id
        JOIN department d ON d.department_id = e.department_id
        LEFT JOIN cr ON cr.employee_id = days.employee_id AND cr.work_date = days.work_date
        LEFT JOIN att ON att.employee_id = days.employee_id AND att.work_date = days.work_date
        ${WHERE_SQL}
      `;
      const result = await listOf(db, selectSql, '"sortWorkDate", "sortEmployeeId", "attendanceType"', filter);
      result.items = result.items.map((row: any) => {
        const { sortEmployeeId, sortWorkDate, ...rest } = row;
        return rest;
      });
      return result;
    });
  }

  @Get('/attendance-status/monthly')
  async listMonthlyAttendanceStatus(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자');
    const filter = readFilter(req, user);
    return transaction(async (db) => {
      const selectSql = `
        SELECT e.name AS "employeeName",
               d.name AS "departmentName",
               to_char(att.work_date, 'YYYY-MM') AS "month",
               CAST(COUNT(DISTINCT att.work_date) AS integer) AS "attendanceDays"
        FROM att
        JOIN employee e ON e.employee_id = att.employee_id
        JOIN department d ON d.department_id = e.department_id
        ${WHERE_SQL}
        GROUP BY e.employee_id, e.name, d.name, to_char(att.work_date, 'YYYY-MM')
      `;
      return listOf(db, selectSql, '"month", "employeeName"', filter);
    });
  }

  @Get('/attendance-status/summary')
  async listAttendanceSummary(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자');
    const filter = readFilter(req, user);
    return transaction(async (db) => {
      const selectSql = `
        SELECT att.attendance_type AS "attendanceType",
               CAST(COUNT(*) AS integer) AS "count"
        FROM att
        JOIN employee e ON e.employee_id = att.employee_id
        ${WHERE_SQL}
        GROUP BY att.attendance_type
      `;
      return listOf(db, selectSql, '"attendanceType"', filter);
    });
  }
}

