import { useState } from 'react';
import {
  Band,
  DataTable,
  DateInput,
  DateText,
  ErrorText,
  Field,
  Filters,
  LookupSelect,
  Num,
  Pager,
  Select,
  call,
  useData,
} from '../kit';
import type { Column, Page, PageProps, Row } from '../kit';

const VIEWS: [string, string][] = [
  ['daily', '일별 현황'],
  ['monthly', '월별 현황'],
  ['summary', '유형별 집계'],
];

const SCOPES: [string, string][] = [
  ['전체', '전체'],
  ['부서', '부서'],
  ['개인', '개인'],
];

const PATHS: Record<string, string> = {
  daily: '/attendance-status/daily',
  monthly: '/attendance-status/monthly',
  summary: '/attendance-status/summary',
};

const SIZE = 20;

export default function FnSfr01805Page({ role, notify }: PageProps) {
  const [view, setView] = useState('daily');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [scope, setScope] = useState('개인');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [pageNo, setPageNo] = useState(0);
  const [formError, setFormError] = useState('');

  const { data, error, loading } = useData<Page>(async () => {
    if (applied === null) {
      return { items: [], page: 0, size: SIZE, total: 0 };
    }
    return call<Page>('GET', PATHS[view], role, undefined, { ...applied, page: pageNo, size: SIZE });
  }, [view, applied, pageNo, role]);

  function search() {
    if (startDate === '' || endDate === '') {
      setFormError('조회 기간의 시작일과 종료일을 입력해 주세요.');
      return;
    }
    if (startDate > endDate) {
      setFormError('조회 시작일은 종료일보다 늦을 수 없습니다.');
      return;
    }
    if (scope === '부서' && departmentId === '') {
      setFormError('부서 범위로 조회하려면 부서를 선택해 주세요.');
      return;
    }
    setFormError('');
    setPageNo(0);
    setApplied({ startDate, endDate, scope, departmentId, employeeId });
    notify('조건에 맞는 근태 현황을 조회했습니다.');
  }

  function reset() {
    setStartDate('');
    setEndDate('');
    setScope('개인');
    setDepartmentId('');
    setEmployeeId('');
    setApplied(null);
    setPageNo(0);
    setFormError('');
  }

  const dailyColumns: Column[] = [
    { key: 'employeeName', label: '임직원명' },
    { key: 'departmentName', label: '부서명' },
    { key: 'workDate', label: '근무일자', render: (r) => <DateText value={r.workDate} /> },
    {
      key: 'checkInAt',
      label: '출퇴근시각',
      render: (r) => (
        <span>
          <DateText value={r.checkInAt} time /> ~ <DateText value={r.checkOutAt} time />
        </span>
      ),
    },
    { key: 'attendanceType', label: '근태 유형' },
  ];

  const monthlyColumns: Column[] = [
    { key: 'employeeName', label: '임직원명' },
    { key: 'departmentName', label: '부서명' },
    { key: 'month', label: '집계 월' },
    { key: 'attendanceDays', label: '월 근태 일수', render: (r) => <Num value={r.attendanceDays} /> },
  ];

  const summaryColumns: Column[] = [
    { key: 'attendanceType', label: '근태 유형' },
    { key: 'count', label: '유형별 건수', render: (r) => <Num value={r.count} /> },
  ];

  const columns = view === 'daily' ? dailyColumns : view === 'monthly' ? monthlyColumns : summaryColumns;

  return (
    <div className='doc'>
      <section className='box'>
        <h2>근태 현황 및 집계</h2>
        <div>
          {VIEWS.map(([key, label]) => (
            <button
              key={key}
              className={view === key ? '' : 'ghost'}
              onClick={() => {
                setView(key);
                setPageNo(0);
              }}
            >
              {label}
            </button>
          ))}
        </div>
        <Filters onSearch={search} onReset={reset}>
          <Field label='조회 시작일' required>
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label='조회 종료일' required>
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label='조회 범위(전체/부서/개인)' required>
            <Select value={scope} onChange={setScope} options={SCOPES} placeholder='범위 선택' />
          </Field>
          <Field label='부서 ID'>
            <LookupSelect table='department' role={role} value={departmentId} onChange={setDepartmentId} placeholder='부서 선택' />
          </Field>
          <Field label='임직원 ID'>
            <LookupSelect table='employee' role={role} value={employeeId} onChange={setEmployeeId} placeholder='임직원 선택' />
          </Field>
        </Filters>
        {formError !== '' && <ErrorText text={formError} />}
        {error !== '' && <ErrorText text={error} />}
      </section>
      <section className='box'>
        <h2>{VIEWS.find(([key]) => key === view)?.[1]}</h2>
        <Band total={data?.total} />
        <DataTable
          columns={columns}
          rows={data?.items ?? []}
          empty={applied === null ? '조회 조건을 입력하고 조회 버튼을 눌러 주세요.' : loading ? '불러오는 중입니다.' : '조건에 맞는 근태 내역이 없습니다.'}
        />
        <Pager page={pageNo} size={SIZE} total={data?.total ?? 0} onPage={setPageNo} />
      </section>
    </div>
  );
}
